struct chunk_file;

struct chunk_flavor
{
    char name[16];
    chunk_flavor() { __builtin_strcpy(name, ""); }
    bool operator==(const chunk_flavor &) const;
};

struct stringx
{
    char data[8];
    stringx();
    ~stringx();
};

struct color
{
    float r;
    float g;
    float b;
    float a;
};

extern chunk_flavor CHUNK_TEXTURE;
extern chunk_flavor CHUNK_TEXFLAGS;
extern chunk_flavor CHUNK_TEXINFO;
extern chunk_flavor CHUNK_DETINFO;
extern chunk_flavor CHUNK_ENVIRONMENT;
extern chunk_flavor CHUNK_DIFFUSE_COLOR;
extern chunk_flavor CHUNK_FLAGS;
extern chunk_flavor CHUNK_END;

__asm__(".equ CHUNK_TEXTURE, 0x0045B5C0");
__asm__(".equ CHUNK_TEXFLAGS, 0x0045B5D0");
__asm__(".equ CHUNK_TEXINFO, 0x0045B5E0");
__asm__(".equ CHUNK_DETINFO, 0x0045B5F0");
__asm__(".equ CHUNK_ENVIRONMENT, 0x0045B600");
__asm__(".equ CHUNK_DIFFUSE_COLOR, 0x0045B610");
__asm__(".equ CHUNK_FLAGS, 0x0045B630");
__asm__(".equ CHUNK_END, 0x0045B528");
__asm__(".equ __eq__C12chunk_flavorRC12chunk_flavor, 0x00336B60");
__asm__(".equ __7stringx, 0x0034D3E0");
__asm__(".equ _$_7stringx, 0x0034D6E0");

void serial_in(chunk_file &, chunk_flavor *);
void serial_in(chunk_file &, unsigned *);
void serial_in(chunk_file &, float *);
void serial_in(chunk_file &, stringx *);
void serial_in(chunk_file &, color *);

__asm__(".equ serial_in__FR10chunk_fileP12chunk_flavor, 0x00336800");
__asm__(".equ serial_in__FR10chunk_filePUi, 0x00336930");
__asm__(".equ serial_in__FR10chunk_filePf, 0x00336998");
__asm__(".equ serial_in__FR10chunk_fileP7stringx, 0x003369F8");

void skip_material_chunk(chunk_file &io)
{
    for (;;)
    {
        chunk_flavor cf;
        serial_in(io, &cf);
        if (CHUNK_TEXTURE == cf)
        {
            stringx filename;
            serial_in(io, &filename);
        }
        else if (CHUNK_TEXFLAGS == cf)
        {
            unsigned flags;
            serial_in(io, &flags);
        }
        else if (CHUNK_TEXINFO == cf)
        {
            unsigned mode;
            serial_in(io, &mode);
            float amt;
            serial_in(io, &amt);
        }
        else if (CHUNK_DETINFO == cf)
        {
            float f;
            serial_in(io, &f);
            serial_in(io, &f);
            serial_in(io, &f);
            serial_in(io, &f);
        }
        else if (CHUNK_ENVIRONMENT == cf)
        {
            stringx filename;
            serial_in(io, &filename);
        }
        else if (CHUNK_DIFFUSE_COLOR == cf)
        {
            color c;
            serial_in(io, &c);
        }
        else if (CHUNK_FLAGS == cf)
        {
            unsigned flags;
            serial_in(io, &flags);
        }
        else if (CHUNK_END == cf)
        {
            break;
        }
    }
}
